package icepunk_backend.controller;
import icepunk_backend.dto.CreateContentReportRequest; import icepunk_backend.model.User; import icepunk_backend.repository.UserRepository; import icepunk_backend.service.ContentReportService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController public class ContentReportController { private final ContentReportService service; private final UserRepository users; private final icepunk_backend.service.AuthRateLimitService limits; public ContentReportController(ContentReportService s,UserRepository u,icepunk_backend.service.AuthRateLimitService l){service=s;users=u;limits=l;} @PostMapping("/reports") public ResponseEntity<Void> create(Authentication a,@Valid @RequestBody CreateContentReportRequest r){User u=users.findByEmail(a.getName()).orElseThrow();limits.checkReportLimit(u.getId());service.create(u,r);return ResponseEntity.accepted().build();}}
